```python
# Forward-chain explicit facts and rules, keeping negation distinct.
facts = {
    ("suspects", "duck", "butterfly"),
    ("named", "fish", "Paco"),
    ("named", "reindeer", "Peddi"),
    ("not_hugs", "ant", "flamingo"),
}

rules = [
    (
        {
            ("named", "fish", "Paco"),
            ("named", "reindeer", "Peddi"),
        },
        ("hugs", "reindeer", "crab"),
    ),
    (
        {("suspects", "duck", "butterfly")},
        ("suspects", "duck", "otter"),
    ),
    (
        {("not_hugs", "ant", "flamingo")},
        ("reveals_secret", "flamingo", "otter"),
    ),
    (
        {
            ("reveals_secret", "flamingo", "otter"),
            ("suspects", "duck", "otter"),
        },
        ("not_hides_cards", "otter", "dragon"),
    ),
]

# Rule 1's name-initial condition must also hold.
assert "Paco"[0] == "Peddi"[0]

changed = True
while changed:
    changed = False
    for antecedents, conclusion in rules:
        if antecedents <= facts and conclusion not in facts:
            facts.add(conclusion)
            changed = True

positive = ("hides_cards", "otter", "dragon")
negative = ("not_hides_cards", "otter", "dragon")
if positive in facts and negative in facts:
    result = "inconsistent"
elif positive in facts:
    result = "proved"
elif negative in facts:
    result = "disproved"
else:
    result = "unknown"

submitted = "proved"  # Normalize submitted "Proven."
print("Duck suspects otter:", ("suspects", "duck", "otter") in facts)
print("Flamingo reveals secret to otter:",
      ("reveals_secret", "flamingo", "otter") in facts)
print("Otter hides cards from dragon:", positive in facts)
print("Otter does not hide cards from dragon:", negative in facts)
print("Expected result:", result)
print("CHECK PASS" if result == submitted else "CHECK FAIL")
